import "core-js/modules/es.array.push.js";
import { ref, computed, onMounted, onUnmounted, nextTick, watch } from 'vue';
import EmojiPicker from '@/components/EmojiPicker.vue'; // 导入表情包组件
import { useRoute, useRouter } from 'vue-router';
import { useStore } from 'vuex';
import defaultAvatar from '@/assets/default-avatar.png';
import { API_CONFIG } from '@/config/config';
import { ElMessage, ElNotification } from 'element-plus';
import axios from 'axios';
import CryptoUtils from '@/utils/crypto';
export default {
  components: {
    EmojiPicker
  },
  setup() {
    const route = useRoute();
    const router = useRouter();
    const store = useStore();
    const messagesContainer = ref(null);
    const targetUser = ref({});
    const messages = ref([]);
    const inputMessage = ref('');
    const myAvatar = computed(() => {
      const user = store.state.user;
      return user.photo ? `${API_CONFIG.BASE_URL}${user.photo}` : defaultAvatar;
    });
    const socket = ref(null);
    const isConnected = ref(false);
    const reconnecting = ref(false);
    const reconnectTimer = ref(null);
    const myId = computed(() => store.state.user.id);
    const myUser = computed(() => store.state.user);
    const cryptoUtils = new CryptoUtils();

    // 新增变量
    const showEmojiPicker = ref(false);
    const messageInput = ref(null);
    const fileInput = ref(null);
    const uploadProgress = ref(0);
    const isUploading = ref(false);

    // 工具方法：处理图片URL
    const getFullUrl = path => {
      if (!path) return defaultAvatar;
      return path.startsWith('http') ? path : `${API_CONFIG.BASE_URL}${path}`;
    };

    // 新增工具方法：从URL提取文件名
    const getFileName = url => {
      if (!url) return '文件';
      const parts = url.split('/');
      return parts[parts.length - 1] || '文件';
    };

    // 工具方法：格式化时间
    const formatTime = time => {
      if (!time) return '';
      const date = new Date(time);
      const now = new Date();
      if (date.toDateString() === now.toDateString()) {
        return date.toTimeString().substring(0, 5);
      }
      const yesterday = new Date();
      yesterday.setDate(now.getDate() - 1);
      if (date.toDateString() === yesterday.toDateString()) {
        return '昨天';
      }
      return `${date.getMonth() + 1}/${date.getDate()}`;
    };

    // 初始化WebSocket连接
    const initWebSocket = () => {
      if (myId.value && targetUser.value.id) {
        const wsUrl = `ws://${API_CONFIG.URL_CHAT}/ws/chat/${myId.value}/${targetUser.value.id}`;
        if (socket.value) {
          socket.value.close();
        }
        socket.value = new WebSocket(wsUrl);
        socket.value.onopen = () => {
          isConnected.value = true;
          reconnecting.value = false;
          ElNotification({
            title: '连接成功',
            message: `已与 ${targetUser.value.username || '对方'} 建立聊天连接`,
            type: 'success',
            duration: 3000
          });

          // 连接成功后加载历史消息
          loadHistoryMessages();
        };
        socket.value.onmessage = async event => {
          try {
            const messageData = JSON.parse(event.data);
            let msg;
            if (messageData.encrypt_data && messageData.publick_key) {
              msg = await cryptoUtils.decrypt(messageData.encrypt_data, messageData.publick_key);
            } else {
              msg = messageData;
            }

            // 处理消息，支持media字段
            addMessage({
              id: msg.id,
              text: msg.text,
              media: msg.media || [],
              fromMe: msg.from === myId.value,
              time: msg.time
            });

            // 更新最近聊天列表
            const senderInfo = {
              id: parseInt(msg.from, 10),
              username: msg.fromUsername || '未知用户',
              photo: msg.fromPhoto
            };
            store.commit('chat/ADD_RECENT_CHAT', senderInfo);
            store.dispatch('chat/saveRecentChat');
          } catch (e) {
            console.error('解析消息失败', e);
            ElMessage.error('接收消息失败');
          }
        };
        socket.value.onclose = () => {
          isConnected.value = false;
          ElNotification({
            title: '连接断开',
            message: '聊天连接已断开，正在尝试重连...',
            type: 'warning',
            duration: 0
          });
          if (!reconnecting.value) {
            startReconnect();
          }
        };
        socket.value.onerror = errorEvent => {
          console.error('WebSocket错误', errorEvent);
          ElMessage.error('聊天连接错误，请稍后再试');
        };
      }
    };

    // 加载历史消息
    const loadHistoryMessages = async () => {
      if (myId.value && targetUser.value.id) {
        try {
          const res = await axios.get(`${API_CONFIG.BASE_URL}/ws/chat/history/${myId.value}/${targetUser.value.id}`, {
            headers: {
              Authorization: `Bearer ${store.state.token}`
            }
          });
          if (res.data && res.data.length) {
            const cryptoUtils = new CryptoUtils();
            const decryptedMessages = [];
            for (const encryptedMsg of res.data) {
              try {
                const decryptedMsg = await cryptoUtils.decrypt(encryptedMsg.encrypt_data, encryptedMsg.publick_key);

                // 转换消息格式，支持media字段
                decryptedMessages.push({
                  id: decryptedMsg.id,
                  text: decryptedMsg.text,
                  media: decryptedMsg.media || [],
                  from_id: decryptedMsg.from_id,
                  target_id: myId.value,
                  fromMe: decryptedMsg.from_id === myId.value,
                  time: decryptedMsg.created_at
                });
              } catch (decryptError) {
                console.error("解密历史消息失败:", decryptError);
              }
            }
            messages.value = decryptedMessages;
            nextTick(() => {
              if (messagesContainer.value) {
                messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
              }
            });
          }
        } catch (err) {
          console.error('加载历史消息失败', err);
          ElMessage.warning('历史消息加载失败');
        }
      }
    };

    // 开始重连
    const startReconnect = () => {
      if (reconnecting.value || !targetUser.value.id) return;
      reconnecting.value = true;
      reconnectTimer.value = setTimeout(() => {
        initWebSocket();
        reconnecting.value = false;
      }, 3000);
    };

    // 停止重连
    const stopReconnect = () => {
      if (reconnectTimer.value) {
        clearTimeout(reconnectTimer.value);
        reconnectTimer.value = null;
        reconnecting.value = false;
      }
    };

    // 添加消息到列表
    const addMessage = msg => {
      messages.value.push(msg);
      nextTick(() => {
        if (messagesContainer.value) {
          messagesContainer.value.scrollTop = messagesContainer.value.scrollHeight;
        }
      });
    };

    // 切换表情包选择器显示状态
    const toggleEmojiPicker = () => {
      showEmojiPicker.value = !showEmojiPicker.value;
      if (showEmojiPicker.value) {
        nextTick(() => {
          if (messageInput.value) {
            messageInput.value.focus();
          }
        });
      }
    };

    // 处理文件上传
    const handleFileUpload = async event => {
      const file = event.target.files[0];
      if (!file) return;
      try {
        isUploading.value = true;
        uploadProgress.value = 0;

        // 创建表单数据
        const formData = new FormData();
        formData.append('file', file);

        // 上传文件
        const res = await axios.post(`${API_CONFIG.BASE_URL}/upload/media`, formData, {
          headers: {
            'Content-Type': 'multipart/form-data',
            'Authorization': `Bearer ${store.state.token}`
          },
          onUploadProgress: progressEvent => {
            uploadProgress.value = Math.round(progressEvent.loaded * 100 / progressEvent.total);
          }
        });
        if (res.data.success) {
          // 构建媒体消息
          const mediaType = res.data.type;
          const mediaUrl = res.data.url;

          // 发送媒体消息
          sendMediaMessage(mediaType, mediaUrl);

          // 显示上传成功提示
          ElMessage.success(`${mediaType === 'image' ? '图片' : mediaType === 'video' ? '视频' : '文件'}上传成功`);
        } else {
          ElMessage.error('上传失败：' + res.data.message);
        }
      } catch (error) {
        console.error('文件上传错误', error);
        ElMessage.error('上传失败，请重试');
      } finally {
        isUploading.value = false;
        uploadProgress.value = 0;

        // 重置文件输入
        if (fileInput.value) {
          fileInput.value.value = '';
        }
      }
    };

    // 发送媒体消息
    const sendMediaMessage = (type, url) => {
      if (!isConnected.value) {
        ElMessage.warning('当前连接已断开，无法发送消息');
        return;
      }
      const msg = {
        id: Date.now(),
        text: '',
        media: [{
          type,
          url
        }],
        fromMe: true,
        time: new Date().toISOString()
      };
      addMessage(msg);
      try {
        // 发送消息
        socket.value.send(JSON.stringify({
          id: msg.id,
          text: '',
          media: msg.media,
          time: msg.time,
          from: myId.value,
          to: targetUser.value.id,
          fromUsername: myUser.value.username,
          fromPhoto: myUser.value.photo
        }));
      } catch (error) {
        console.error('发送媒体消息失败', error);
        ElMessage.error('消息发送失败，请稍后再试');
      }

      // 更新最近聊天列表
      store.commit('chat/ADD_RECENT_CHAT', targetUser.value);
      store.dispatch('chat/saveRecentChat');
    };

    // 发送消息
    const sendMessage = () => {
      // 空内容拦截（强化提示）
      const content = inputMessage.value.trim();
      if (!content && (!messages.media || messages.media.length === 0)) {
        ElMessage.warning('消息内容不能为空，请输入后再发送～');
        return;
      }
      if (!isConnected.value) {
        ElMessage.warning('当前连接已断开，无法发送消息');
        return;
      }
      const msg = {
        id: Date.now(),
        text: inputMessage.value.trim(),
        fromMe: true,
        time: new Date().toISOString()
      };
      addMessage(msg);
      inputMessage.value = '';
      try {
        // 发送消息
        socket.value.send(JSON.stringify({
          id: msg.id,
          text: msg.text,
          time: msg.time,
          from: myId.value,
          to: targetUser.value.id,
          fromUsername: myUser.value.username,
          fromPhoto: myUser.value.photo
        }));
      } catch (error) {
        console.error('发送消息失败', error);
        ElMessage.error('消息发送失败，请稍后再试');
      }

      // 更新最近聊天列表
      store.commit('chat/ADD_RECENT_CHAT', targetUser.value);
      store.dispatch('chat/saveRecentChat');
    };

    // 返回上一页
    const goBack = () => {
      router.back();
      stopReconnect();
      if (socket.value) {
        socket.value.close();
      }
    };

    // 监听路由参数变化
    watch(() => route.params.userId, newId => {
      if (newId) {
        fetchUserInfo(newId);
      }
    });

    // 获取用户信息
    const fetchUserInfo = userId => {
      axios.get(`${API_CONFIG.BASE_URL}/user/info`, {
        params: {
          id: userId
        },
        headers: {
          Authorization: `Bearer ${store.state.token}`
        }
      }).then(res => {
        if (res.data && res.data.id) {
          targetUser.value = res.data;
          initWebSocket();
        } else {
          console.error("res : ", res.data);
          throw new Error('用户信息为空');
        }
      }).catch(err => {
        console.log("失败： ", userId);
        console.error('获取用户信息失败', err);
        ElMessage.error('获取用户信息失败');
        router.back();
      });
    };
    onMounted(() => {
      if (route.params.userId) {
        fetchUserInfo(route.params.userId);
      } else {
        ElMessage.error('未指定聊天对象');
        router.back();
      }
    });
    onUnmounted(() => {
      stopReconnect();
      if (socket.value) {
        socket.value.close();
      }
    });
    return {
      targetUser,
      messages,
      inputMessage,
      myAvatar,
      getFullUrl,
      getFileName,
      formatTime,
      sendMessage,
      goBack,
      messagesContainer,
      isConnected,
      showEmojiPicker,
      messageInput,
      fileInput,
      uploadProgress,
      isUploading,
      toggleEmojiPicker,
      handleFileUpload
    };
  }
};
